// File: reproduce.js
const { CLIEngine } = require("eslint");

// Create an instance of ESLint’s CLIEngine with no-constant-condition turned on
const cli = new CLIEngine({
  useEslintrc: false,
  baseConfig: {
    parserOptions: { ecmaVersion: 2015 },
    rules: {
      // enable the rule that’s mis-reporting its range
      "no-constant-condition": "error"
    }
  }
});

// The source text that triggers the bug
const source = `
if (true) {
  something();
}

something(true ? 1 : 0);
`;

// Run ESLint on the text
const report = cli.executeOnText(source, "test.js");

// Print the raw JSON so you can inspect the reported ranges
console.log(JSON.stringify(report, null, 2));
